  --accent: #6366f1;
  --accent-hover: #818cf8;
  --danger: #ef4444;
  --danger-hover: #f87171;
  --radius: 12px;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem;
}

/* ── Image preview card ── */
.image-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  width: 320px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
}

.image-card__preview {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  display: block;
  background: var(--surface-2);
}

/* Placeholder gradient when no real image */
.image-card__preview--placeholder {
  background: linear-gradient(135deg, #1e2235 0%, #2a2f4a 50%, #1e2235 100%);
  display: flex;
  align-items: center;
  justify-content: center;
}

.image-card__preview--placeholder svg {
  opacity: 0.25;
}

.image-card__body {
  padding: 1rem 1.25rem 1.25rem;
}

.image-card__name {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  margin-bottom: 0.25rem;
}

.image-card__meta {
  font-size: 0.8125rem;
  color: var(--text-muted);
  margin-bottom: 1rem;
}

.image-card__actions {
  display: flex;
  gap: 0.625rem;
}

/* ── Buttons ── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.5rem 1rem;
  border: none;
  border-radius: 8px;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, box-shadow 0.15s;
  text-decoration: none;
}

.btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.btn--ghost {
  background: var(--surface-2);
  color: var(--text-muted);
  border: 1px solid var(--border);
  flex: 1;
}

.btn--ghost:hover {
  background: #2b3050;
  color: var(--text);
}

.btn--danger-outline {
  background: transparent;
  color: var(--danger);
  border: 1px solid var(--danger);
  flex: 1;
}

.btn--danger-outline:hover {
  background: rgba(239, 68, 68, 0.1);
}

.btn--primary {
  background: var(--accent);
  color: #fff;
}

.btn--primary:hover {
  background: var(--accent-hover);
}

.btn--danger {
  background: var(--danger);
  color: #fff;
}

.btn--danger:hover {
  background: var(--danger-hover);
  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.25);
}

.btn--cancel {
  background: var(--surface-2);
  color: var(--text-muted);
  border: 1px solid var(--border);
}

.btn--cancel:hover {
  background: #2b3050;
  color: var(--text);
}

/* ── Overlay / backdrop ── */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.7);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  z-index: 100;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.2s, visibility 0.2s;
}

.modal-overlay.is-open {
  opacity: 1;
  visibility: visible;
}

/* ── Modal dialog ── */
.modal {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  width: 100%;
  max-width: 420px;
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.7);
  transform: translateY(12px) scale(0.97);
  transition: transform 0.2s;
}

.modal-overlay.is-open .modal {
  transform: translateY(0) scale(1);
}

.modal__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem 0;
}

.modal__icon {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: rgba(239, 68, 68, 0.15);
  border: 1px solid rgba(239, 68, 68, 0.3);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.modal__close {
  background: none;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  padding: 0.375rem;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s, color 0.15s;
  margin-left: auto;
}

.modal__close:hover {
  background: var(--surface-2);
  color: var(--text);
}

.modal__close:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.modal__body {
  padding: 1rem 1.5rem 1.5rem;
}

.modal__title {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--text);
  margin: 0.875rem 0 0.5rem;
}

.modal__description {
  font-size: 0.9rem;
  color: var(--text-muted);
