}

.modal__filename {
  color: var(--text);
  font-weight: 500;
}

.modal__divider {
  height: 1px;
  background: var(--border);
  margin: 1.25rem 0;
}

.modal__actions {
  display: flex;
  gap: 0.75rem;
  justify-content: flex-end;
}
